// k6 — simulate 2,000 teams submitting metadata in 10 minutes (PS2).
// Files themselves go direct-to-S3; this stresses the API control plane.
//
// PAIRS_FILE: JSON array of { t: accessToken, team: teamId, h: hackathonId }
// generated by `server/src/tmp-k6pairs.ts` (one entry per team leader).
// Run: k6 run load/submissions.js
import http from 'k6/http';
import { check } from 'k6';
// open() is a k6 global — no import needed

export const options = {
  scenarios: {
    deadline_crush: {
      executor: 'constant-arrival-rate',
      rate: 200,          // 200 submissions/min → 2,000 in 10 min
      timeUnit: '1m',
      duration: '10m',
      preAllocatedVUs: 100,
      maxVUs: 300,
    },
  },
  thresholds: {
    http_req_duration: ['p(95)<300'],
    http_req_failed: ['rate<0.02'],
  },
};

const BASE = __ENV.BASE_URL || 'http://localhost:4000';
// open() is only available in the init stage — load pairs at module scope.
const PAIRS = __ENV.PAIRS_FILE ? JSON.parse(open(__ENV.PAIRS_FILE)) : null;
if (PAIRS && !PAIRS.length) throw new Error('PAIRS_FILE is empty');

export function setup() {
  if (PAIRS) return { pairs: PAIRS };
  // Fallback: single token/team mode (local smoke)
  const email = `k6-${Date.now()}@load.dev`;
  const res = http.post(`${BASE}/api/auth/register`, JSON.stringify({
    email, password: 'password123', displayName: 'k6 user',
  }), { headers: { 'Content-Type': 'application/json' } });
  return { token: JSON.parse(res.body).accessToken, hackathonId: __ENV.HACKATHON_ID, teamId: __ENV.TEAM_ID };
}

export default function (data) {
  const pair = data.pairs
    ? data.pairs[Math.floor(Math.random() * data.pairs.length)]
    : { t: data.token, team: data.teamId, h: data.hackathonId };
  const res = http.post(`${BASE}/api/submissions`, JSON.stringify({
    hackathonId: pair.h,
    teamId: pair.team,
    title: `Submission ${__ITER}`,
    links: ['https://example.com'],
  }), { headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${pair.t}` } });
  check(res, { 'created': (r) => r.status === 201 || r.status === 409 });
}
